examples:
可表示为：
```cpp
class Base {
public:
    virtual void go(int value = 2);
};

class Derived : public Base {
public:
    void go(int value = 7) override;
};

Base b;
Derived d;
Base& ref = d;

b.go();    // 使用默认参数 2，执行 Base::go(2)
d.go();    // 使用默认参数 7，执行 Derived::go(7)
ref.go();  // 使用默认参数 2，但执行 Derived::go(2)
```
